/* 去重：与 data.js 已有条目、以及本文件内部重复的方程式只保留首次出现 */
const __eqKey = s => String(s)
  .replace(/<sub>(\d+)<\/sub>/g, "$1")
  .replace(/<[^>]+>/g, "")
  .replace(/\{\{.*?\}\}/g, "")
  .replace(/[\s\u00a0↑↓]/g, "")
  .replace(/（/g, "(").replace(/）/g, ")");
const __seen = new Set(EQ.map(x => __eqKey(x.e)));
const __kept = EQ_EXTRA.filter(x => {
  const k = __eqKey(x.e);
  if (__seen.has(k)) return false;
  __seen.add(k);
  return true;
});
if (__kept.length !== EQ_EXTRA.length) {
  console.info("[data-extra] 去重 " + EQ_EXTRA.length + " → " + __kept.length);
}
EQ.push(...__kept);


